def parse_args(argv):
    opts = Options()
    special = None
    i=0
    while i < len(argv):
        a=argv[i]
        if a == '--':
            opts.paths.extend(argv[i+1:]); break
        if a in ('--help','-h'):
            special='help'; i+=1; continue
        if a == '--version':
            special='version'; i+=1; continue
        if a in ('--languages','-l'):
            special='languages'; i+=1; continue
        if a.startswith('--'):
            name=a; val=None
            if '=' in a:
                name,val=a.split('=',1)
            if name in BOOL_FLAGS:
                setattr(opts, BOOL_FLAGS[name], True)
                i+=1; continue
            if name in VALUE_FLAGS:
                if val is None:
                    if i+1>=len(argv):
                        eprint(f"Error: flag needs an argument: '{name[2:]}' in {name}")
                        eprint(usage_only())
                        return None, None, 1
                    val=argv[i+1]; i+=2
                else:
                    i+=1
                field=VALUE_FLAGS[name]
                if field.startswith('_'):
                    continue
                try:
                    assign_value(opts, field, val, name)
                except ValueError as ex:
                    eprint(str(ex)); eprint(usage_only()); return None,None,1
                continue
            eprint(f"Error: unknown flag: {name}")
            eprint(usage_only())
            return None, None, 1
        if a.startswith('-') and a != '-':
            # support simple short flags and one value flag at a time
            if a in SHORT_BOOL:
                field=SHORT_BOOL[a]
                setattr(opts, field, True)
                i+=1; continue
            if a in SHORT_VALUE:
                if i+1>=len(argv):
                    eprint(f"Error: flag needs an argument: '{a[1:]}' in {a}")
                    eprint(usage_only()); return None,None,1
                val=argv[i+1]; i+=2
                try:
                    assign_value(opts, SHORT_VALUE[a], val, a)
                except ValueError as ex:
                    eprint(str(ex)); eprint(usage_only()); return None,None,1
                continue
            # handle grouped booleans like -pc conservatively
            ok=True
            for ch in a[1:]:
                key='-'+ch
                if key not in SHORT_BOOL:
                    ok=False; break
                setattr(opts, SHORT_BOOL[key], True)
            if ok:
                i+=1; continue
            eprint(f"Error: unknown shorthand flag: '{a[1:2]}' in {a}")
