def csv_escape(s, quote=False):
    s=str(s)
    if quote or any(c in s for c in ',"\n'):
        return '"'+s.replace('"','""')+'"'
    return s


def format_csv(summaries, opts):
    out=[]
    if opts.by_file:
        out.append('Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,ULOC')
        files=[f for s in summaries for f in s.files]
        for f in files:
            out.append(','.join(map(str,[f.language,f.location,f.filename,f.lines,f.code,f.comment,f.blank,0 if opts.no_complexity else f.complexity,f.bytes,f.uloc if opts.uloc else 0])))
    else:
        out.append('Language,Lines,Code,Comments,Blanks,Complexity,Bytes,Files,ULOC')
        for s in summaries:
            out.append(','.join(map(str,[s.name,s.lines,s.code,s.comment,s.blank,0 if opts.no_complexity else s.complexity,s.bytes,s.count,s.uloc if opts.uloc else 0])))
