    fps=int(total.count/elapsed) if elapsed else 0
    lps=int(total.lines/elapsed) if elapsed else 0
    out=['# https://github.com/boyter/scc/','header:','  url: https://github.com/boyter/scc/',f'  version: {VERSION}',f'  elapsed_seconds: {elapsed:.3f}',f'  n_files: {total.count}',f'  n_lines: {total.lines}',f'  files_per_second: {fps}',f'  lines_per_second: {lps}']
    for s in summaries:
        key=s.name.replace(':','')
        out += [f'{key}:',f'  name: {s.name}',f'  code: {s.code}',f'  comment: {s.comment}',f'  blank: {s.blank}',f'  nFiles: {s.count}']
    out += ['SUM:',f'  code: {total.code}',f'  comment: {total.comment}',f'  blank: {total.blank}',f'  nFiles: {total.count}']
    return '\n'.join(out)+'\n'


