def detect_shebang(data):
    first = data.splitlines()[0].lower() if data.splitlines() else ''
    if not first.startswith('#!'):
        return None
    if 'python' in first: return 'Python'
    if 'bash' in first: return 'BASH'
    if 'zsh' in first: return 'Zsh'
    if 'sh' in first: return 'Shell'
    if 'ruby' in first: return 'Ruby'
    if 'perl' in first: return 'Perl'
    if 'php' in first: return 'PHP'
    if 'node' in first or 'javascript' in first: return 'JavaScript'
    return None


def parse_remap(spec):
    mappings=[]
    if not spec: return mappings
    # split on commas not in quotes, accept key:value pairs
    parts=[]; cur=''; q=False
    for ch in spec:
        if ch=='"': q=not q; cur+=ch
        elif ch==',' and not q:
            parts.append(cur); cur=''
        else: cur+=ch
    if cur: parts.append(cur)
    for p in parts:
        if ':' in p:
            k,v=p.split(':',1)
            mappings.append((k.strip().strip('"'), v.strip().strip('"')))
    return mappings


def language_from_count_as(opts):
    m={}
    for k,v in parse_remap(opts.count_as):
        ext=k.lower().lstrip('.')
        val=v.strip()
        lang = EXT_MAP.get(val.lower().lstrip('.'), val)
        m[ext]=lang
    return m


def identify_language(path, data, opts, count_as_map):
    base=os.path.basename(path)
    lowbase=base.lower()
    ext=''
    # special multi extension d.ts
    if lowbase.endswith('.d.ts'):
        ext='d.ts'
    elif '.' in base:
        ext=base.rsplit('.',1)[1].lower()
    if ext in count_as_map:
        return count_as_map[ext], ext
    if lowbase in count_as_map:
        return count_as_map[lowbase], ext or lowbase
    # filename matches take precedence for extensionless/common names
    if lowbase in FILE_MAP:
        return FILE_MAP[lowbase], ext or lowbase
    if ext and ext in EXT_MAP:
        return EXT_MAP[ext], ext
    if not ext:
        sh=detect_shebang(data)
        if sh: return sh, ''
    # remap unknown by content
    for needle, lang in parse_remap(opts.remap_unknown):
        if needle and needle in data:
            return lang, ext
    return None, ext


def should_skip_path(path, root_rel, opts, ignore_patterns):
    base=os.path.basename(path)
    if base in opts.exclude_file:
        return True
    if not opts.count_ignore and base in ('.gitignore','.ignore','.sccignore'):
        return True
    for pat in opts.not_match:
        try:
            if re.search(pat, path) or re.search(pat, root_rel):
                return True
        except re.error:
            pass
    for pat in ignore_patterns:
        if match_ignore(pat, root_rel, base):
            return True
    return False


def match_ignore(pat, rel, base):
    pat=pat.strip()
    if not pat or pat.startswith('#'):
        return False
    neg=pat.startswith('!')
    if neg: return False
    pat=pat.lstrip('/')
    if pat.endswith('/'):
        return rel.startswith(pat[:-1]+'/') or base==pat[:-1]
    return fnmatch.fnmatch(rel, pat) or fnmatch.fnmatch(base, pat)


def read_ignore_patterns(root, opts):
    pats=[]
    files=[]
    if not opts.no_gitignore: files.append('.gitignore')
    if not opts.no_ignore: files.append('.ignore')
    if not opts.no_scc_ignore: files.append('.sccignore')
    for f in files:
        p=os.path.join(root,f)
        try:
            with open(p,'r',encoding='utf-8',errors='ignore') as fh:
                pats.extend([x.strip() for x in fh if x.strip()])
        except OSError:
            pass
    return pats


def iter_files(paths, opts):
    out=[]
    for inpath in paths:
        p=os.path.abspath(inpath)
        if not os.path.exists(p):
            eprint(f"file or directory could not be read: {inpath}")
            return None, 1
        if os.path.isfile(p) or (os.path.islink(p) and opts.include_symlinks):
            out.append((p, os.path.basename(inpath)))
        elif os.path.isdir(p):
            ignore_patterns=read_ignore_patterns(p, opts)
            for dirpath, dirnames, filenames in os.walk(p, followlinks=opts.include_symlinks):
                rel_dir=os.path.relpath(dirpath,p)
                if rel_dir=='.': rel_dir=''
                newdirs=[]
                for d in dirnames:
                    rel=os.path.join(rel_dir,d) if rel_dir else d
                    if d in opts.exclude_dir or match_any_dir(d, rel, opts, ignore_patterns):
                        continue
                    newdirs.append(d)
                dirnames[:] = sorted(newdirs)
                for fn in sorted(filenames):
                    fp=os.path.join(dirpath,fn)
                    if os.path.islink(fp) and not opts.include_symlinks:
                        continue
                    rel=os.path.join(rel_dir,fn) if rel_dir else fn
                    if should_skip_path(fp, rel, opts, ignore_patterns):
                        continue
                    out.append((fp, rel))
        else:
            eprint(f"file or directory could not be read: {inpath}")
            return None,1
    return out,0


def match_any_dir(d, rel, opts, pats):
    for pat in opts.not_match:
        try:
            if re.search(pat, rel) or re.search(pat, d): return True
        except re.error: pass
    for pat in pats:
        if match_ignore(pat, rel, d): return True
    return False


def is_binary_bytes(b):
    return b'\x00' in b[:8192]


def strip_strings_for_complexity(s):
    # Good enough for keywords in simple code; avoids most quoted strings.
    s=re.sub(r'"(?:\\.|[^"\\])*"', ' ', s)
    s=re.sub(r"'(?:\\.|[^'\\])*'", ' ', s)
    return s


def split_code_comment(line, lang, state):
    # Returns (has_code, has_comment, new_state). Lines with both are code, matching scc's displayed counts.
    styles = COMMENT_STYLES.get(lang, {'line':[], 'block':[]})
    i=0; has_code=False; has_comment=False; s=line
    while i < len(s):
        if state:
            end=state[1]
            has_comment=True
            j=s.find(end,i)
            if j<0:
                return has_code, has_comment, state
            i=j+len(end); state=None; continue
        # whitespace
        if s[i].isspace():
            i+=1; continue
        # block starts
        found=None
        for st,en in styles.get('block',[]):
            if s.startswith(st,i):
                found=(st,en); break
        if found:
            has_comment=True
            end=found[1]
            j=s.find(end,i+len(found[0]))
            if j<0:
                state=found; return has_code, has_comment, state
            i=j+len(end); continue
        # line comments only if they are first non-space part of remaining line; inline comments don't make comment count
        matched_line=False
        for lc in styles.get('line',[]):
            if s.startswith(lc,i):
                has_comment=True
                return has_code, has_comment, state
        # code char; consume until next possible comment marker to handle code before block comment
        has_code=True
        nexts=[]
        for st,en in styles.get('block',[]):
            j=s.find(st,i+1)
            if j>=0: nexts.append(j)
        for lc in styles.get('line',[]):
            j=s.find(lc,i+1)
            if j>=0: nexts.append(j)
        if nexts:
            i=min(nexts)
        else:
            break
    return has_code, has_comment, state


def count_complexity_line(line, lang, is_code):
    if not is_code:
        return 0
    s=strip_strings_for_complexity(line)
    if lang in ('Markdown','Plain Text','JSON','YAML','TOML','XML','HTML','License','CSV'):
        return 0
    kws = ['if','for','while','case','catch','elif','except','when','unless']
    count=0
    for kw in kws:
        count += len(re.findall(r'\b'+re.escape(kw)+r'\b', s))
    count += s.count('&&') + s.count('||')
    # switch/select/match add mild complexity for many languages
    count += len(re.findall(r'\b(switch|select|match)\b', s))
    return count


def count_file(path, rel, opts, count_as_map):
    try:
        b=Path(path).read_bytes()
    except OSError:
        return None
    if is_binary_bytes(b) and not opts.binary:
        return None
    size=len(b)
    try:
        text=b.decode('utf-8')
    except UnicodeDecodeError:
        text=b.decode('utf-8','replace')
    lang, ext = identify_language(path, text, opts, count_as_map)
    # remap-all works even when a language was found
    for needle, rlang in parse_remap(opts.remap_all):
        if needle and needle in text:
            lang=rlang
            break
    if not lang:
        return None
    if opts.include_ext and ext.lower().lstrip('.') not in [x.lower().lstrip('.') for x in opts.include_ext]:
        return None
    if opts.exclude_ext and ext.lower().lstrip('.') in [x.lower().lstrip('.') for x in opts.exclude_ext]:
        return None
    lines = text.splitlines()
    # Python splitlines gives [] for empty, and counts final unterminated line as one, matching observations.
    total=len(lines)
    if opts.no_large and (size > opts.large_byte_count or total > opts.large_line_count):
        return None
    lowhead='\n'.join(lines[:20]).lower()
    generated=any(m.lower() in lowhead for m in opts.generated_markers)
    # minified/generated based on average physical line length
    avg = (size / total) if total else 0
    minified = avg >= opts.min_gen_line_length and total > 0
    if opts.no_gen and generated:
        return None
    if opts.no_min and minified:
        return None
    lang_label=lang
    if opts.gen and generated:
        lang_label = lang_label + ' (gen)'
    if opts.min and minified:
        lang_label = lang_label + ' (min)'
    blank=comment=code=complexity=0
    state=None
    for line in lines:
        if line.strip()=='':
            blank+=1; continue
        has_code, has_comment, state = split_code_comment(line, lang, state)
        if has_code:
            code+=1
        elif has_comment:
            comment+=1
        else:
            code+=1
        complexity += count_complexity_line(line, lang, has_code)
    # If a line is inside an unclosed block state and had no explicit code, split_code_comment already marks comments.
    fs=FileStat(language=lang_label, possible=[lang], filename=os.path.basename(path), extension=ext, location=rel.replace(os.sep,'/'),
                bytes=size, lines=total, code=code, comment=comment, blank=blank, complexity=complexity,
                content_lines=lines, binary=is_binary_bytes(b), minified=minified, generated=generated)
    if opts.uloc:
        fs.uloc=len(set(lines))
    return fs


def collect(opts):
    files,rc=iter_files(opts.paths, opts)
    if rc: return None, rc
    count_as_map=language_from_count_as(opts)
    stats=[]; seen_hash=set()
    for p,rel in files:
        fs=count_file(p,rel,opts,count_as_map)
        if not fs: continue
        if opts.no_duplicates:
            try: h=hashlib.sha1(Path(p).read_bytes()).hexdigest()
            except OSError: h=None
            if h and h in seen_hash: continue
            if h: seen_hash.add(h)
        stats.append(fs)
    summaries={}
    for fs in stats:
        s=summaries.setdefault(fs.language, Summary(name=fs.language))
        s.bytes += fs.bytes; s.lines += fs.lines; s.code += fs.code; s.comment += fs.comment; s.blank += fs.blank
        s.complexity += (0 if opts.no_complexity else fs.complexity)
        s.count += 1; s.files.append(fs)
        if opts.character:
            for ln in fs.content_lines: s.line_lengths.append(len(ln))
    if opts.uloc:
        for s in summaries.values():
            all_lines=[]
            for f in s.files: all_lines.extend(f.content_lines)
            s.uloc=len(set(all_lines))
            for f in s.files: f.uloc=len(set(f.content_lines))
    arr=list(summaries.values())
    sort_summaries(arr, opts.sort)
    for s in arr:
        sort_files(s.files, opts.sort)
    return arr,0


def sort_summaries(arr, key):
    key=(key or 'files').lower()
    def val(s):
        if key=='name': return (s.name.lower(),)
        mapping={'files':s.count,'lines':s.lines,'blanks':s.blank,'comments':s.comment,'comment':s.comment,'code':s.code,'complexity':s.complexity}
        return (-mapping.get(key,s.count), s.name.lower())
    arr.sort(key=val)


def sort_files(arr, key):
    key=(key or 'files').lower()
    if key=='name': arr.sort(key=lambda f:f.location.lower()); return
    mapping=lambda f: {'files':1,'lines':f.lines,'blanks':f.blank,'comments':f.comment,'comment':f.comment,'code':f.code,'complexity':f.complexity}.get(key,f.lines)
    arr.sort(key=lambda f:(-mapping(f), f.location.lower()))


def totals(summaries):
    return Summary(name='Total', bytes=sum(s.bytes for s in summaries), lines=sum(s.lines for s in summaries),
                   code=sum(s.code for s in summaries), comment=sum(s.comment for s in summaries), blank=sum(s.blank for s in summaries),
                   complexity=sum(s.complexity for s in summaries), count=sum(s.count for s in summaries),
                   uloc=sum(s.uloc for s in summaries))


def border(opts, wide=False):
    if opts.no_hborder: return ''
    return (WIDE_LIGHT if (opts.ci and wide) else WIDE_HEAVY if wide else LIGHT if opts.ci else HEAVY)


def format_row_complex(name, files, lines, blanks, comments, code, complexity):
    name=ellipsize(name,17)
    return f"{name:<17} {comma(files):>7} {comma(lines):>11} {comma(blanks):>9} {comma(comments):>9} {comma(code):>10} {comma(complexity):>10}"


def format_row_nocomp(name, files, lines, blanks, comments, code):
    name=ellipsize(name,26)
    return f"{name:<26} {comma(files):>7} {comma(lines):>11} {comma(blanks):>10} {comma(comments):>11} {comma(code):>10}"


def format_file_row_complex(name, lines, blanks, comments, code, complexity):
    name=ellipsize(name,26)
    return f"{name:<26} {comma(lines):>10} {comma(blanks):>9} {comma(comments):>9} {comma(code):>10} {comma(complexity):>10}"


def format_file_row_nocomp(name, lines, blanks, comments, code):
    name=ellipsize(name,36)
    return f"{name:<36} {comma(lines):>10} {comma(blanks):>9} {comma(comments):>11} {comma(code):>10}"


def ellipsize(s, width):
    if len(s) <= width: return s
    if width <= 1: return s[:width]
    return s[:width-1] + '…'


def cocomo(opts, code):
    typ=opts.cocomo_project_type or 'organic'
    if typ.startswith('custom,'):
        parts=typ.split(',')
        try: a,b,c,d=map(float, parts[1:5])
        except Exception: a,b,c,d=2.4,1.05,2.5,0.38
        label='custom'
    elif typ == 'semi-detached':
        a,b,c,d=3.0,1.12,2.5,0.35; label=typ
    elif typ == 'embedded':
        a,b,c,d=3.6,1.20,2.5,0.32; label=typ
    else:
        a,b,c,d=2.4,1.05,2.5,0.38; label='organic'
    kloc=max(code,0)/1000.0
    effort=a*(kloc**b)*opts.eaf if kloc>0 else 0.0
    schedule=c*(effort**d) if effort>0 else 0.0
    people=effort/schedule if schedule>0 else 0.0
    cost=people*schedule*(opts.avg_wage/12.0)*opts.overhead
    return label, cost, schedule, people, effort, (a,b,c,d)


def size_line(opts, bytecount):
    unit=(opts.size_unit or 'si').lower()
    if unit == 'binary':
        mb=bytecount/(1024*1024)
        return f"Processed {bytecount} bytes, {mb:.3f} mebibytes (binary)"
    mb=bytecount/1000000.0
    return f"Processed {bytecount} bytes, {mb:.3f} megabytes (SI)"


def format_tabular(summaries, opts):
    total=totals(summaries)
    lines=[]; b=border(opts)
    if b: lines.append(b)
    if opts.no_complexity:
        lines.append(format_row_nocomp('Language','Files','Lines','Blanks','Comments','Code'))
    else:
        lines.append(format_row_complex('Language','Files','Lines','Blanks','Comments','Code','Complexity'))
    if b: lines.append(b)
    for s in summaries:
        if opts.no_complexity:
            lines.append(format_row_nocomp(s.name,s.count,s.lines,s.blank,s.comment,s.code))
        else:
            lines.append(format_row_complex(s.name,s.count,s.lines,s.blank,s.comment,s.code,s.complexity))
        extra_printed=False
        if opts.by_file:
            if b: lines.append(b)
            for f in s.files:
                if opts.no_complexity:
                    lines.append(format_file_row_nocomp(f.location,f.lines,f.blank,f.comment,f.code))
                else:
                    lines.append(format_file_row_complex(f.location,f.lines,f.blank,f.comment,f.code,0 if opts.no_complexity else f.complexity))
            extra_printed=True
        if opts.percent:
            lines.append(format_percent_row(s,total,opts.no_complexity)); extra_printed=True
        if opts.character:
            mx=max(s.line_lengths) if s.line_lengths else 0
            mean=int(sum(s.line_lengths)/len(s.line_lengths)) if s.line_lengths else 0
            lines.append(f"{'MaxLine / MeanLine':<17} {mx:>7} {mean:>11}"); extra_printed=True
        if opts.uloc:
            lines.append(f"{'(ULOC)':<26} {comma(s.uloc):>10}"); extra_printed=True
        if extra_printed:
            if s is not summaries[-1]: lines.append(LIGHT)
    if b: lines.append(b)
    if opts.no_complexity:
        lines.append(format_row_nocomp('Total',total.count,total.lines,total.blank,total.comment,total.code))
    else:
        lines.append(format_row_complex('Total',total.count,total.lines,total.blank,total.comment,total.code,total.complexity))
    if b: lines.append(b)
    if opts.uloc or opts.dryness:
        project_uloc=len(set(ln for s in summaries for f in s.files for ln in f.content_lines))
        if opts.uloc:
            lines.append(f"{'Unique Lines of Code (ULOC)':<26} {comma(project_uloc):>10}")
        if opts.dryness:
            dry=(project_uloc/total.lines) if total.lines else 0.0
            lines.append(f"{'DRYness %':<26} {dry:>10.2f}")
        if b: lines.append(b)
    if not opts.no_cocomo and not opts.sloccount_format:
        label,cost,sched,people,_,_=cocomo(opts,total.code)
        lines.append(f"Estimated Cost to Develop ({label}) {opts.currency_symbol}{comma(int(cost))}")
        lines.append(f"Estimated Schedule Effort ({label}) {sched:.2f} months")
        lines.append(f"Estimated People Required ({label}) {people:.2f}")
        if b: lines.append(b)
    if opts.sloccount_format:
        label,cost,sched,people,effort,params=cocomo(opts,total.code)
        a,bp,c,d=params
        lines.append(f"Total Physical Source Lines of Code (SLOC)                     = {comma(total.code)}")
        lines.append(f"Development Effort Estimate, Person-Years (Person-Months)      = {effort/12:.2f} ({effort:.2f})")
        lines.append(f" (Basic COCOMO model, Person-Months = {a:.2f}*(KSLOC**{bp:.2f})*{opts.eaf:.2f})")
        lines.append(f"Schedule Estimate, Years (Months)                              = {sched/12:.2f} ({sched:.2f})")
        lines.append(f" (Basic COCOMO model, Months = {c:.2f}*(person-months**{d:.2f}))")
        lines.append(f"Estimated Average Number of Developers (Effort/Schedule)       = {people:.2f}")
        lines.append(f"Total Estimated Cost to Develop                                = {opts.currency_symbol}{comma(int(round(cost)))}")
        lines.append(f" (average salary = {opts.currency_symbol}{comma(opts.avg_wage)}/year, overhead = {opts.overhead:.2f})")
        if border(opts): lines.append(border(opts))
    if not opts.no_size:
        lines.append(size_line(opts,total.bytes))
        if border(opts): lines.append(border(opts))
    return '\n'.join(lines)+'\n'


def format_percent_row(s,total,no_complexity):
    def pct(a,b): return '0.0%' if b==0 else f"{100*a/b:.1f}%"
    if no_complexity:
        return f"{'Percentage':<26} {pct(s.count,total.count):>7} {pct(s.lines,total.lines):>11} {pct(s.blank,total.blank):>10} {pct(s.comment,total.comment):>11} {pct(s.code,total.code):>10}"
    return f"{'Percentage':<17} {pct(s.count,total.count):>7} {pct(s.lines,total.lines):>11} {pct(s.blank,total.blank):>9} {pct(s.comment,total.comment):>9} {pct(s.code,total.code):>10} {pct(s.complexity,total.complexity):>10}"


def format_wide(summaries, opts):
    total=totals(summaries); lines=[]; b=border(opts,wide=True)
    if b: lines.append(b)
    lines.append(f"{'Language':<35} {'Files':>8} {'Lines':>9} {'Blanks':>8} {'Comments':>9} {'Code':>8} {'Complexity':>10} {'Complexity/Lines':>16}")
    if b: lines.append(b)
    for s in summaries:
        ratio=(s.complexity/s.code*100) if s.code else 0.0
        lines.append(f"{ellipsize(s.name,35):<35} {comma(s.count):>8} {comma(s.lines):>9} {comma(s.blank):>8} {comma(s.comment):>9} {comma(s.code):>8} {comma(s.complexity):>10} {ratio:>16.2f}")
    if b: lines.append(b)
    # observed total prints 100.00 when any complexity exists
    tratio=100.0 if total.complexity else 0.0
    lines.append(f"{'Total':<35} {comma(total.count):>8} {comma(total.lines):>9} {comma(total.blank):>8} {comma(total.comment):>9} {comma(total.code):>8} {comma(total.complexity):>10} {tratio:>16.2f}")
    if b: lines.append(b)
    if not opts.no_size:
        lines.append(size_line(opts,total.bytes))
        if b: lines.append(b)
    return '\n'.join(lines)+'\n'


def summary_json_obj(s, opts, include_files=False):
    return {
        'Name':s.name,'Bytes':s.bytes,'CodeBytes':0,'Lines':s.lines,'Code':s.code,'Comment':s.comment,
        'Blank':s.blank,'Complexity':0 if opts.no_complexity else s.complexity,'Count':s.count,'WeightedComplexity':0,
        'Files':[file_json_obj(f,opts) for f in s.files] if include_files else [],
        'LineLength': None,'ULOC':s.uloc if opts.uloc else 0
    }


def file_json_obj(f, opts):
    return {'Language':f.language,'PossibleLanguages':f.possible,'Filename':f.filename,'Extension':f.extension,
            'Location':f.location,'Symlocation':'','Bytes':f.bytes,'Lines':f.lines,'Code':f.code,'Comment':f.comment,
            'Blank':f.blank,'Complexity':0 if opts.no_complexity else f.complexity,'WeightedComplexity':0,'Hash':None,
            'Binary':False,'Minified':f.minified,'Generated':f.generated,'EndPoint':0,'Uloc':f.uloc if opts.uloc else 0}


def format_json(summaries, opts):
    return json.dumps([summary_json_obj(s,opts,opts.by_file) for s in summaries], separators=(',',':'))


def format_json2(summaries, opts):
    total=totals(summaries); label,cost,sched,people,_,_=cocomo(opts,total.code)
    obj={'languageSummary':[summary_json_obj(s,opts,opts.by_file) for s in summaries],
         'estimatedCost':cost,'estimatedScheduleMonths':sched,'estimatedPeople':people}
    return json.dumps(obj,separators=(',',':'))


def csv_escape(s, quote=False):
    s=str(s)
    if quote or any(c in s for c in ',"\n'):
        return '"'+s.replace('"','""')+'"'
    return s


def format_csv(summaries, opts):
    out=[]
    if opts.by_file:
        out.append('Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,ULOC')
        files=[f for s in summaries for f in s.files]
        for f in files:
            out.append(','.join(map(str,[f.language,f.location,f.filename,f.lines,f.code,f.comment,f.blank,0 if opts.no_complexity else f.complexity,f.bytes,f.uloc if opts.uloc else 0])))
    else:
        out.append('Language,Lines,Code,Comments,Blanks,Complexity,Bytes,Files,ULOC')
        for s in summaries:
            out.append(','.join(map(str,[s.name,s.lines,s.code,s.comment,s.blank,0 if opts.no_complexity else s.complexity,s.bytes,s.count,s.uloc if opts.uloc else 0])))
    return '\n'.join(out)+'\n'


def format_csv_stream(summaries, opts):
    out=['Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc']
    for s in summaries:
        for f in s.files:
            out.append(','.join([csv_escape(f.language),csv_escape(f.location,True),csv_escape(f.filename,True),str(f.lines),str(f.code),str(f.comment),str(f.blank),str(0 if opts.no_complexity else f.complexity),str(f.bytes),str(f.uloc if opts.uloc else 0)]))
    return '\n'.join(out)+'\n'


def format_cloc_yaml(summaries, opts):
    total=totals(summaries)
    elapsed=0.001
    fps=int(total.count/elapsed) if elapsed else 0
    lps=int(total.lines/elapsed) if elapsed else 0
    out=['# https://github.com/boyter/scc/','header:','  url: https://github.com/boyter/scc/',f'  version: {VERSION}',f'  elapsed_seconds: {elapsed:.3f}',f'  n_files: {total.count}',f'  n_lines: {total.lines}',f'  files_per_second: {fps}',f'  lines_per_second: {lps}']
    for s in summaries:
        key=s.name.replace(':','')
        out += [f'{key}:',f'  name: {s.name}',f'  code: {s.code}',f'  comment: {s.comment}',f'  blank: {s.blank}',f'  nFiles: {s.count}']
    out += ['SUM:',f'  code: {total.code}',f'  comment: {total.comment}',f'  blank: {total.blank}',f'  nFiles: {total.count}']
    return '\n'.join(out)+'\n'


