def format_html_table(summaries, opts):
    total=totals(summaries)
    out=['<table id="scc-table">','\t<thead><tr>']
    for h in ['Language','Files','Lines','Blank','Comment','Code','Complexity','Bytes','Uloc']:
        out.append(f'\t\t<th>{h}</th>')
    out.append('\t</tr></thead>')
    out.append('\t<tbody><tr>')
    # original creates one tr per language with compact separators
    body=[]
    for s in summaries:
        body.append('\t<tbody><tr>' if False else '\t<tr>')
    out=[]
    out.append('<table id="scc-table">')
    out.append('\t<thead><tr>')
    for h in ['Language','Files','Lines','Blank','Comment','Code','Complexity','Bytes','Uloc']:
        out.append(f'\t\t<th>{h}</th>')
    out.append('\t</tr></thead>')
    if summaries:
        first=True
        for s in summaries:
            out.append(('\t<tbody><tr>' if first else '\t<tr>'))
            first=False
            vals=[s.name,s.count,s.lines,s.blank,s.comment,s.code,0 if opts.no_complexity else s.complexity,s.bytes,s.uloc if opts.uloc else 0]
            for v in vals: out.append(f'\t\t<th>{htmlmod.escape(str(v))}</th>')
            out.append('\t</tr>' + ('' if s is not summaries[-1] else '</tbody>'))
    else:
        out.append('\t<tbody></tbody>')
    out.append('\t<tfoot><tr>')
    vals=['Total',total.count,total.lines,total.blank,total.comment,total.code,0 if opts.no_complexity else total.complexity,total.bytes,total.uloc if opts.uloc else 0]
    for v in vals: out.append(f'\t\t<th>{htmlmod.escape(str(v))}</th>')
    out.append('\t</tr></tfoot></table>')
    return '\n'.join(out)


def format_sql(summaries, opts, include_schema=True):
    project=opts.sql_project or ''
    total=totals(summaries); label,cost,sched,people,_,_=cocomo(opts,total.code)
    out=[]
    if include_schema:
        out += ['create table metadata (   -- github.com/boyter/scc v 3.7.0',
                '             timestamp text,','             Project   text,','             elapsed_s real,',
                '             estimated_cost real,','             estimated_schedule_months real,','             estimated_people real);',
                'create table t        (','             Project       text   ,','             Language      text   ,','             File          text   ,','             File_dirname  text   ,','             File_basename text   ,','             nByte         integer,','             nBlank        integer,','             nComment      integer,','             nCode         integer,','             nComplexity   integer,','             nUloc         integer    ',');']
    out.append('begin transaction;')
    for s in summaries:
        for f in s.files:
            d=os.path.dirname(f.location); base=os.path.basename(f.location)
            out.append(f"insert into t values('{sqlq(project)}', '{sqlq(f.language)}', '{sqlq(f.location)}', '{sqlq(d)}', '{sqlq(base)}', {f.bytes}, {f.blank}, {f.comment}, {f.code}, {0 if opts.no_complexity else f.complexity}, {f.uloc if opts.uloc else 0});")
    out.append('commit;')
    out.append('begin transaction;')
    ts=datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    out.append(f"insert into metadata values('{ts}', '{sqlq(project)}', {0.001:.6f}, {cost:.6f}, {sched:.6f}, {people:.6f});")
    out.append('commit;')
    return '\n'.join(out)+'\n'


def sqlq(s): return str(s).replace("'","''")


def render(summaries, opts, fmt=None):
    fmt=(fmt or opts.fmt or 'tabular').lower()
    if opts.wide and fmt=='tabular':
        return format_wide(summaries, opts)
    if fmt == 'wide': return format_wide(summaries, opts)
    if fmt == 'json': return format_json(summaries, opts)
    if fmt == 'json2': return format_json2(summaries, opts)
    if fmt == 'csv': return format_csv(summaries, opts)
    if fmt == 'csv-stream': return format_csv_stream(summaries, opts)
    if fmt == 'cloc-yaml': return format_cloc_yaml(summaries, opts)
    if fmt == 'openmetrics': return format_openmetrics(summaries, opts)
    if fmt == 'html-table': return format_html_table(summaries, opts)
    if fmt == 'html': return '<html lang="en"><head><meta charset="utf-8" /><title>scc html output</title><style>table { border-collapse: collapse; }td, th { border: 1px solid #999; padding: 0.5rem; text-align: left;}</style></head><body>'+format_html_table(summaries, opts)+'</body></html>\n'
    if fmt == 'sql': return format_sql(summaries, opts, True)
    if fmt == 'sql-insert': return '\n'+format_sql(summaries, opts, False)
    # unknown formats fall back to tabular, as observed for -f nope.
    return format_tabular(summaries, opts)


def handle_output(text, opts):
    if opts.output and opts.output != 'stdout':
        with open(opts.output,'w',encoding='utf-8') as f: f.write(text)
        sys.stdout.write(f"results written to {opts.output}\n")
    else:
        sys.stdout.write(text)


def run_mcp():
    # A tiny harmless placeholder; real scc starts a JSON-RPC stdio server. This keeps the process responsive for smoke tests.
    for line in sys.stdin:
        if not line.strip(): continue
        try:
            req=json.loads(line)
            resp={'jsonrpc':'2.0','id':req.get('id'),'result':{}}
            sys.stdout.write(json.dumps(resp)+'\n'); sys.stdout.flush()
        except Exception:
            pass


def main(argv=None):
    if argv is None: argv=sys.argv[1:]
    opts,special,rc=parse_args(argv)
    if rc: return rc
    if special=='help':
        sys.stdout.write(HELP_TEXT); return 0
    if special=='version':
        sys.stdout.write(f"scc version {VERSION}\n"); return 0
    if special=='languages':
        sys.stdout.write(LANGUAGES_TEXT); return 0
    if opts.mcp:
        run_mcp(); return 0
    summaries,rc=collect(opts)
    if rc: return rc
    if opts.format_multi:
        # format: fmt:target,fmt:file ; stdout is printed, files are written.
        for part in parse_csv(opts.format_multi):
            if ':' in part:
                fmt,target=part.split(':',1)
            else:
                fmt,target=part,'stdout'
            text=render(summaries, opts, fmt)
            if target == 'stdout': sys.stdout.write(text)
            else:
                with open(target,'w',encoding='utf-8') as f: f.write(text)
        return 0
    text=render(summaries, opts)
    handle_output(text, opts)
    return 0

if __name__ == '__main__':
    sys.exit(main())
